// HttpClient (od Javy 11) to nowoczesne API do wysylania zadan HTTP.
// Odpowiedz odbieramy jako zwykly String - na tym etapie to jeszcze
// CZYSTY TEKST, nie mamy pojecia, ze to JSON, dopoki go nie sparsujemy.

HttpClient client = HttpClient.newHttpClient();
HttpRequest request = HttpRequest.newBuilder()
        .uri(URI.create("http://localhost:" + port + "/api/users"))
        .header("Accept", "application/json")
        .GET()
        .build();

HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
System.out.println(response.body()); // surowy tekst JSON

// Mamy String z tekstem JSON - zamieniamy go na liste obiektow User
// przy pomocy Gson. Ponieważ chcemy List<User> (typ generyczny),
// potrzebujemy TypeToken - bez niego Gson zwrocilby surowe LinkedTreeMap.

Gson gson = new Gson();
Type userListType = new TypeToken<List<User>>() {}.getType();
List<User> users = gson.fromJson(response.body(), userListType);

users.forEach(user -> System.out.println(user.name() + " " + user.email()));
System.out.println(users.get(0).getClass().getSimpleName()); // "User", nie LinkedTreeMap

// Tak samo jak pobieramy dane, moglibysmy je WYSLAC np. przez POST -
// wystarczy zserializowac obiekt Java do JSON-a (gson.toJson(...))
// i wyslac jako cialo zadania z naglowkiem Content-Type: application/json.

User nowyUzytkownik = new User(4, "Piotr Zielinski", "piotr@example.com");
String json = new GsonBuilder().setPrettyPrinting().create().toJson(nowyUzytkownik);
System.out.println(json);
// {
//   "id": 4,
//   "name": "Piotr Zielinski",
//   "email": "piotr@example.com"
// }
